'use client'

import { useAdminSession } from './AdminSessionContext'
import { canAdminWrite } from '@/data/admin-nav'
import { AdminDashboardCommandBoard } from './AdminDashboardCommandBoard'

export function AdminDashboard() {
  const session = useAdminSession()
  const canWrite = canAdminWrite(session.role)

  return (
    <>
      <AdminDashboardCommandBoard
        canWrite={canWrite}
        displayName={session.displayName || 'Admin HMTE'}
      />
    </>
  )
}
