'use client'

import Link from 'next/link'
import { limit, orderBy, where, type QueryConstraint, type Timestamp } from 'firebase/firestore'
import { useEffect, useMemo, useRef, useState } from 'react'
import { divisionsByCode } from '@/data/divisions'
import { hasFirebaseConfig } from '@/lib/firebase/client'
import { countContentDocuments, subscribeToContentDocuments } from '@/lib/firebase/content-services'
import { getAgendaYear, normalizeProgramMonths, parseIsoDate } from '@/lib/program-schedule'
import type { AnnouncementDocument, ArticleDocument, AuditLogDocument, FirestoreCollectionName, ProgramDocument } from '@/types/firestore'

type DashboardBoardData = {
  articles: ArticleDocument[]
  announcements: AnnouncementDocument[]
  changes: AuditLogDocument[]
  programs: ProgramDocument[]
}

type PulseCounts = {
  total: number | null
  draft: number | null
  published: number | null
  loading: boolean
  error: string
}

const emptyData: DashboardBoardData = { articles: [], announcements: [], changes: [], programs: [] }
const emptyPulseCounts: PulseCounts = { total: null, draft: null, published: null, loading: true, error: '' }

const entityLabels: Record<AuditLogDocument['entityType'], string> = {
  announcements: 'Pengumuman', articles: 'Berita', divisions: 'Divisi', downloads: 'Berkas', gallery: 'Galeri',
  leaders: 'Pengurus', media: 'Media', mediaSlots: 'Slot media', pageContents: 'Halaman', pageContentDrafts: 'Draf halaman',
  partners: 'Mitra', programs: 'Program kerja', settings: 'Pengaturan', siteSettingsDrafts: 'Draf pengaturan',
}

const actionLabels: Record<AuditLogDocument['action'], string> = {
  create: 'Dibuat', update: 'Diperbarui', delete: 'Dihapus', restore: 'Dipulihkan',
}

function timestampMillis(value: Timestamp | null | undefined) {
  return value && typeof value.toMillis === 'function' ? value.toMillis() : 0
}

function formatDate(value: Timestamp | null | undefined) {
  const milliseconds = timestampMillis(value)
  if (!milliseconds) return 'Belum tersedia'
  return new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'Asia/Makassar' }).format(new Date(milliseconds))
}

function formatRelativeDate(value: Timestamp | null | undefined) {
  const milliseconds = timestampMillis(value)
  if (!milliseconds) return 'Waktu belum tersedia'
  const minutes = Math.max(0, Math.floor((Date.now() - milliseconds) / 60000))
  if (minutes < 1) return 'Baru saja'
  if (minutes < 60) return `${minutes} menit lalu`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours} jam lalu`
  const days = Math.floor(hours / 24)
  if (days < 7) return `${days} hari lalu`
  return formatDate(value)
}

function formatDateOnly(value: Date) {
  return new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'Asia/Makassar' }).format(value)
}

function formatEffectiveDate(value: string, fallback: Timestamp | null | undefined) {
  const parsed = parseIsoDate(value)
  return parsed ? formatDateOnly(parsed) : value.trim() || formatDate(fallback)
}

function getMakassarToday() {
  const parts = new Intl.DateTimeFormat('en-CA', { day: '2-digit', month: '2-digit', timeZone: 'Asia/Makassar', year: 'numeric' }).formatToParts(new Date())
  const values = Object.fromEntries(parts.map((part) => [part.type, part.value]))
  return parseIsoDate(`${values.year}-${values.month}-${values.day}`) ?? new Date()
}

function getAgendaContext() {
  const today = getMakassarToday()
  const year = getAgendaYear()
  const month = today.getUTCFullYear() === year ? today.getUTCMonth() + 1 : undefined
  return {
    year,
    month,
    label: month ? new Intl.DateTimeFormat('id-ID', { month: 'long', timeZone: 'Asia/Makassar' }).format(today) : `periode ${year}`,
  }
}

function getAgendaItems(programs: ProgramDocument[]) {
  const today = getMakassarToday()
  const currentMonth = today.getUTCFullYear() === getAgendaYear() ? today.getUTCMonth() + 1 : 0
  const horizon = new Date(today)
  horizon.setUTCDate(horizon.getUTCDate() + 45)
  const items = programs
    .filter((program) => program.active)
    .map((program) => {
      const date = parseIsoDate(program.startDate)
      return { date, isUpcoming: Boolean(date && date >= today && date <= horizon), program }
    })
    .filter((item): item is { date: Date; isUpcoming: true; program: ProgramDocument } => Boolean(item.date && item.isUpcoming))
    .sort((first, second) => first.date.getTime() - second.date.getTime())
    .slice(0, 3)
  const undated = programs
    .filter((program) => program.active && !parseIsoDate(program.startDate) && normalizeProgramMonths(program.months).includes(currentMonth))
    .sort((first, second) => first.order - second.order)
    .slice(0, 3)
  return { items, undated }
}

function getProgramStatus(program: ProgramDocument) {
  const date = parseIsoDate(program.startDate)
  if (date) return `Mulai ${formatDateOnly(date)}`
  if (normalizeProgramMonths(program.months).length > 0) return 'Bulan rencana tersedia'
  return 'Tanggal perlu dilengkapi'
}

function getProgramMeta(program: ProgramDocument) {
  const divisionName = divisionsByCode[program.divisionCode]?.name
  const startDate = parseIsoDate(program.startDate)
  const planLabel = startDate ? formatDateOnly(startDate) : typeof program.date === 'string' ? program.date.trim() : ''
  return `${program.divisionCode} · ${planLabel && planLabel.toUpperCase() !== program.divisionCode ? planLabel : divisionName || 'Program kerja'}`
}

function isProgramInMonth(program: ProgramDocument, month: number | undefined) {
  if (!month) return true
  const startDate = parseIsoDate(program.startDate)
  if (startDate) return startDate.getUTCFullYear() === getAgendaYear() && startDate.getUTCMonth() + 1 === month
  return normalizeProgramMonths(program.months).includes(month)
}

function sumCounts(values: Array<number | null>) {
  return values.every((value): value is number => typeof value === 'number') ? values.reduce((total, value) => total + value, 0) : null
}

type AdminDashboardCommandBoardProps = { canWrite: boolean; displayName: string }

export function AdminDashboardCommandBoard({ canWrite, displayName }: AdminDashboardCommandBoardProps) {
  const firebaseConfigured = hasFirebaseConfig()
  const [data, setData] = useState<DashboardBoardData>(emptyData)
  const [isLoading, setIsLoading] = useState(firebaseConfigured)
  const [error, setError] = useState(firebaseConfigured ? '' : 'Firebase belum dikonfigurasi. Data kanal belum dapat dimuat.')
  const [sourceErrors, setSourceErrors] = useState<Record<string, string>>(firebaseConfigured ? {} : {
    announcements: 'Firebase belum dikonfigurasi.', articles: 'Firebase belum dikonfigurasi.', changes: 'Firebase belum dikonfigurasi.', programs: 'Firebase belum dikonfigurasi.',
  })
  const [pulseCounts, setPulseCounts] = useState<PulseCounts>(firebaseConfigured ? emptyPulseCounts : { ...emptyPulseCounts, loading: false, error: 'Firebase belum dikonfigurasi.' })
  const loadedSources = useRef(new Set<string>())

  useEffect(() => {
    if (!firebaseConfigured) return
    loadedSources.current.clear()
    const markLoaded = (source: string) => {
      loadedSources.current.add(source)
      if (loadedSources.current.size === 4) setIsLoading(false)
    }
    const handleError = (source: string, loadError: Error) => {
      setSourceErrors((current) => ({ ...current, [source]: loadError.message || 'Sumber data gagal dimuat.' }))
      setError(loadError.message || 'Data kanal belum dapat dimuat.')
      markLoaded(source)
    }
    const unsubscribeArticles = subscribeToContentDocuments<ArticleDocument>('articles', {
      onData: (articles) => { setData((current) => ({ ...current, articles })); markLoaded('articles') },
      onError: (loadError) => handleError('articles', loadError),
    }, [where('status', '==', 'published'), orderBy('publishedAt', 'desc'), limit(3)])
    const unsubscribeAnnouncements = subscribeToContentDocuments<AnnouncementDocument>('announcements', {
      onData: (announcements) => { setData((current) => ({ ...current, announcements })); markLoaded('announcements') },
      onError: (loadError) => handleError('announcements', loadError),
    }, [where('status', '==', 'published'), orderBy('date', 'desc'), limit(3)])
    const unsubscribeChanges = subscribeToContentDocuments<AuditLogDocument>('auditLogs', {
      onData: (changes) => { setData((current) => ({ ...current, changes })); markLoaded('changes') },
      onError: (loadError) => handleError('changes', loadError),
    }, [orderBy('createdAt', 'desc'), limit(3)])
    const unsubscribePrograms = subscribeToContentDocuments<ProgramDocument>('programs', {
      onData: (programs) => { setData((current) => ({ ...current, programs })); markLoaded('programs') },
      onError: (loadError) => handleError('programs', loadError),
    }, [where('active', '==', true)])
    return () => { unsubscribeArticles(); unsubscribeAnnouncements(); unsubscribeChanges(); unsubscribePrograms() }
  }, [firebaseConfigured])

  useEffect(() => {
    if (!firebaseConfigured) return
    let active = true
    const countSpecs: Array<[FirestoreCollectionName, QueryConstraint[]]> = [
      ['articles', []], ['articles', [where('status', '==', 'draft')]], ['articles', [where('status', '==', 'published')]],
      ['announcements', []], ['announcements', [where('status', '==', 'draft')]], ['announcements', [where('status', '==', 'published')]],
      ['gallery', []], ['gallery', [where('status', '==', 'draft')]], ['gallery', [where('status', '==', 'published')]],
    ]
    void Promise.allSettled(countSpecs.map(([collectionName, constraints]) => countContentDocuments(collectionName, constraints))).then((results) => {
      if (!active) return
      const values = results.map((result) => result.status === 'fulfilled' ? result.value : null)
      setPulseCounts({
        total: sumCounts([values[0], values[3], values[6]]),
        draft: sumCounts([values[1], values[4], values[7]]),
        published: sumCounts([values[2], values[5], values[8]]),
        loading: false,
        error: results.some((result) => result.status === 'rejected') ? 'Ringkasan jumlah konten sebagian belum tersedia.' : '',
      })
    })
    return () => { active = false }
  }, [firebaseConfigured])

  const latestArticles = useMemo(() => data.articles.filter((article) => article.status === 'published').slice(0, 3), [data.articles])
  const latestAnnouncements = useMemo(() => data.announcements.filter((announcement) => announcement.status === 'published').slice(0, 3), [data.announcements])
  const agendaPrograms = useMemo(() => data.programs.filter((program) => program.active).sort((first, second) => first.order - second.order), [data.programs])
  const { items: upcomingAgenda, undated: undatedPrograms } = useMemo(() => getAgendaItems(data.programs), [data.programs])
  const agendaContext = useMemo(() => getAgendaContext(), [])
  const agendaMonthPrograms = useMemo(() => agendaPrograms.filter((program) => isProgramInMonth(program, agendaContext.month)), [agendaContext.month, agendaPrograms])
  const agendaCards = agendaMonthPrograms.slice(0, 8)
  const priorityProgram = useMemo(() => agendaMonthPrograms.find((program) => program.featured) ?? upcomingAgenda[0]?.program ?? agendaMonthPrograms[0] ?? agendaPrograms.find((program) => program.featured) ?? agendaPrograms[0], [agendaMonthPrograms, agendaPrograms, upcomingAgenda])
  const boardError = error || pulseCounts.error
  const sourceCount = pulseCounts.total === null ? null : pulseCounts.total + agendaPrograms.length
  const displayFirstName = displayName.trim().split(/\s+/)[0] || 'Admin'
  const toneNames = ['green', 'blue', 'violet', 'amber', 'teal', 'sky', 'indigo', 'navy']

  return (
    <div className="admin-v7-dashboard" aria-busy={isLoading}>
      <header className="admin-v7-intro">
        <div className="admin-v7-intro-copy"><p className="admin-v7-eyebrow">{agendaContext.label} {agendaContext.year} · Kabinet Abya Vistara</p><h1>Selamat bekerja, {displayFirstName}.</h1></div>
        {canWrite ? <Link className="admin-v7-button admin-v7-button-primary" href="/admin/articles/new"><span aria-hidden="true">+</span> Buat publikasi</Link> : null}
      </header>
      {boardError ? <p className="admin-v7-board-alert" role="alert">Sebagian data belum tersedia. Bagian yang berhasil terhubung tetap ditampilkan.</p> : null}

      <section className="admin-v7-command-surface" aria-label="Ringkasan kerja hari ini">
        {priorityProgram ? <Link className="admin-v7-surface-feature" href="/admin/programs"><span className="admin-v7-feature-top"><span>Prioritas periode ini</span><b>{priorityProgram.divisionCode}</b></span><h2>{priorityProgram.name}</h2><p>{priorityProgram.summary || priorityProgram.desc || 'Program kerja yang siap diolah menjadi informasi publik.'}</p><span className="admin-v7-feature-bottom"><span className="admin-v7-feature-arrow" aria-hidden="true">↗</span>Buka program</span></Link> : <div className="admin-v7-surface-feature is-empty"><span className="admin-v7-feature-top"><span>Prioritas periode ini</span><b>HMTE</b></span><h2>Belum ada prioritas agenda.</h2><p>Program aktif dari Firestore akan muncul di permukaan ini.</p></div>}
        <section className="admin-v7-surface-pulse" aria-labelledby="publicationPulseTitle"><header><span>Ruang publikasi</span><h2 id="publicationPulseTitle">Siap diolah.</h2></header><div><strong className="admin-v7-source-number">{pulseCounts.loading ? '—' : sourceCount ?? '—'}</strong><span>entri organisasi terhubung</span></div><div className="admin-v7-pulse-stages" aria-label="Status publikasi"><span><b>{pulseCounts.loading ? '—' : pulseCounts.draft ?? '—'}</b><small>Draft</small></span><span><b>—</b><small>Tinjau</small></span><span><b>{pulseCounts.loading ? '—' : pulseCounts.published ?? '—'}</b><small>Terbit</small></span></div></section>
      </section>

      <section className="admin-v7-agenda-bento" aria-labelledby="agendaTitle"><header className="admin-v7-agenda-head"><div><p>Agenda bulan ini · {agendaContext.label}</p><h2 id="agendaTitle">Agenda {agendaContext.label} <span>yang siap diteruskan.</span></h2></div><strong>{agendaMonthPrograms.length}<span>kegiatan aktif</span></strong></header><div className="admin-v7-agenda-deck">{isLoading ? <div className="admin-v7-agenda-loading" aria-hidden="true"><span /><span /><span /><span /></div> : agendaCards.length > 0 ? agendaCards.map((program, index) => <Link className={`admin-v7-agenda-card ${index < 2 ? 'is-priority' : ''} admin-v7-agenda-card--${toneNames[index % toneNames.length]}`} href="/admin/programs" key={program.id}><small>{getProgramMeta(program)}</small><h3>{program.name}</h3><span className="admin-v7-agenda-footer"><span>{getProgramStatus(program)}</span><b>Buka agenda ↗</b></span></Link>) : <div className="admin-v7-empty-agenda"><b>Belum ada agenda aktif.</b><span>Program kerja bulan ini dari Firestore akan mengisi kanvas ini.</span><Link href="/admin/programs">Buka Program Kerja ↗</Link></div>}</div></section>

      <section className="admin-v7-operations" aria-labelledby="operationsTitle"><header className="admin-v7-operations-head"><div><p>Pantauan kanal</p><h2 id="operationsTitle">Yang perlu dicek berikutnya.</h2></div><span className="admin-v7-live-chip">Data aktual aktif</span></header><div className="admin-v7-signal-top">
        <section className="admin-v7-signal-lane admin-v7-signal-lane--deadline" aria-labelledby="deadlineTitle"><h3 id="deadlineTitle"><span className="admin-v7-lane-mark" />Agenda terdekat</h3>{isLoading ? <div className="admin-v7-lane-skeleton" aria-hidden="true"><span /><span /></div> : sourceErrors.programs ? <div className="admin-v7-empty-channel"><b>Agenda tidak dapat dimuat.</b><span>Coba buka Program Kerja setelah koneksi pulih.</span></div> : upcomingAgenda.length > 0 ? upcomingAgenda.map(({ date, program }) => <Link className="admin-v7-signal-row admin-v7-deadline-row" href="/admin/programs" key={program.id}><strong>{formatDateOnly(date)}</strong><span className="admin-v7-signal-copy"><span>{program.name}</span><small>{program.divisionCode} · {getProgramStatus(program)}</small></span><i>↗</i></Link>) : <div className="admin-v7-empty-channel"><b>Belum ada agenda dengan tanggal dekat.</b><span>Program yang memiliki tanggal mulai akan muncul di sini.</span></div>}{!sourceErrors.programs && undatedPrograms.length > 0 ? <div className="admin-v7-undated-note"><b>{undatedPrograms.length} agenda bulan ini belum memiliki tanggal pasti.</b><span>{undatedPrograms.map((program) => program.name).join(' · ')}</span><Link href="/admin/programs">Lengkapi tanggal ↗</Link></div> : null}</section>
        <section className="admin-v7-signal-lane admin-v7-signal-lane--news" aria-labelledby="newsTitle"><h3 id="newsTitle"><span className="admin-v7-lane-mark" />Berita terbaru</h3>{isLoading ? <div className="admin-v7-lane-skeleton" aria-hidden="true"><span /><span /><span /></div> : sourceErrors.articles ? <div className="admin-v7-empty-channel"><b>Berita tidak dapat dimuat.</b><span>Coba lagi setelah koneksi Firestore pulih.</span></div> : latestArticles.length > 0 ? latestArticles.map((article) => <Link className="admin-v7-signal-row" href={canWrite ? `/admin/articles/${article.id}` : '/admin/articles'} key={article.id}><span className="admin-v7-signal-copy"><span>{article.title}</span><small>{article.category} · {formatRelativeDate(article.publishedAt || article.updatedAt || article.createdAt)}</small></span><span className="admin-v7-signal-tag">Aktual</span><i>↗</i></Link>) : <div className="admin-v7-empty-channel"><b>Belum ada berita terbit.</b><span>Berita yang sudah dipublikasikan akan muncul di sini.</span>{canWrite ? <Link href="/admin/articles/new">Buat berita ↗</Link> : null}</div>}</section>
        <section className="admin-v7-signal-lane admin-v7-signal-lane--announcement" aria-labelledby="announcementTitle"><h3 id="announcementTitle"><span className="admin-v7-lane-mark" />Pengumuman terbaru</h3>{isLoading ? <div className="admin-v7-lane-skeleton" aria-hidden="true"><span /><span /><span /></div> : sourceErrors.announcements ? <div className="admin-v7-empty-channel"><b>Pengumuman tidak dapat dimuat.</b><span>Coba lagi setelah koneksi Firestore pulih.</span></div> : latestAnnouncements.length > 0 ? latestAnnouncements.map((announcement) => <Link className="admin-v7-signal-row" href={canWrite ? `/admin/announcements/${announcement.id}` : '/admin/announcements'} key={announcement.id}><span className="admin-v7-signal-copy"><span>{announcement.title}</span><small>{formatEffectiveDate(announcement.date, announcement.publishedAt || announcement.updatedAt || announcement.createdAt)}</small></span><span className="admin-v7-signal-tag">Aktual</span><i>↗</i></Link>) : <div className="admin-v7-empty-channel"><b>Belum ada pengumuman aktif.</b><span>Informasi terbit untuk mahasiswa akan muncul di sini.</span>{canWrite ? <Link href="/admin/announcements/new">Buat pengumuman ↗</Link> : null}</div>}</section>
      </div><section className="admin-v7-change-lane" aria-labelledby="changesTitle"><header><h3 id="changesTitle"><span className="admin-v7-lane-mark" />Perubahan terbaru</h3><Link href="/admin/history">Buka riwayat ↗</Link></header>{isLoading ? <div className="admin-v7-lane-skeleton admin-v7-lane-skeleton--changes" aria-hidden="true"><span /><span /><span /></div> : sourceErrors.changes ? <div className="admin-v7-empty-channel"><b>Riwayat tidak dapat dimuat.</b><span>Audit log membutuhkan sesi admin yang tervalidasi.</span></div> : data.changes.length > 0 ? <div className="admin-v7-change-list">{data.changes.map((change) => <Link className="admin-v7-change-item" href="/admin/history" key={change.id}><span className="admin-v7-change-dot" /><span><b>{change.summary || `${actionLabels[change.action]} ${entityLabels[change.entityType]}`}</b><small>{entityLabels[change.entityType]} · {formatRelativeDate(change.createdAt)}</small></span></Link>)}</div> : <div className="admin-v7-empty-channel"><b>Belum ada riwayat tercatat.</b><span>Perubahan dari panel akan muncul setelah tersimpan.</span></div>}</section></section>
    </div>
  )
}
